namespace ghidra.app.plugin.core.disassembler;

using db;
using docking.action;
using docking.widgets.dialogs;
using ghidra.app.cmd.disassemble;
using ghidra.app.context;
using ghidra.app.context;
using ghidra.framework.plugintool;
using ghidra.program.disassemble;
using ghidra.program.model.address;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.program.model.util;
using ghidra.util;

class SetLengthOverrideAction : ListingContextAction {

	private DisassemblerPlugin plugin;

	public SetLengthOverrideAction(DisassemblerPlugin plugin, string groupName) : base("Modify Instruction Length", plugin.getName())
    {
		this.plugin = plugin;
		setPopupMenuData(
			new MenuData(new string[] { "Modify Instruction Length..." }, null, groupName));
	}

	/* @Override */
	public void actionPerformed(ListingActionContext context) {

		PluginTool tool = plugin.getTool();

		Address address = context.getAddress();
		if (address == null) {
			return;
		}
		Program program = context.getProgram();
		Listing listing = program.getListing();
		Instruction instr = listing.getInstructionAt(address);
		if (instr == null) {
			return;
		}

		int protoLen = instr.getPrototype().getLength();
		if (protoLen == 1) {
			Msg.showError(this, null, "Length Override Error",
				"Length override for 1-byte instruction not allowed");
			return;
		}

		string restoreTip = ", 0=restore";

		string alignTip = "";
		int align = program.getLanguage().getInstructionAlignment();
		if (align != 1) {
			alignTip = ", must be multiple of " + align;
		}

		int minLength = 0;
		long maxLength = Math.min(Instruction.MAX_LENGTH_OVERRIDE, protoLen - 1);

		if (maxLength == 0) {
			// Assume we have an instruction whose length can't be changed
			Msg.showError(this, null, "Length Override Error",
				"The length of a " + protoLen + "-byte instruction may not be overridden!");
			return;
		}

		int currentLengthOverride = getDefaultOffcutLength(program, instr);

		NumberInputDialog dialog = new NumberInputDialog("Override/Restore Instruction Length",
			"Enter byte-length [" + minLength + ".." + maxLength + restoreTip + alignTip + "]",
			currentLengthOverride, minLength, (int) maxLength, false);
		tool.showDialog(dialog);

		if (dialog.wasCancelled()) {
			return;
		}

		string kind = "Set";
		int lengthOverride = dialog.getIntValue();
		if (lengthOverride == 0) {
			if (!instr.isLengthOverridden()) {
				return; // no change
			}
			kind = "Clear";
		}

		try
{
    using (Transaction tx = instr.getProgram().openTransaction(kind + " Length Override"))
    {

			if (lengthOverride == 0) {
				// Clear any code units that may have been created in the offcut
				int trueLength = instr.getParsedLength();
				listing.clearCodeUnits(address.add(currentLengthOverride),
					address.add(trueLength - 1), false);
			}
			instr.setLengthOverride(lengthOverride);

			Address offcutStart = address.add(lengthOverride);
			if (lengthOverride != 0 && isOffcutFlowReference(program, offcutStart)) {
				tool.executeBackgroundCommand(new DisassembleCommand(offcutStart, null, true),
					program);
				removeErrorBookmark(program, offcutStart);
			}
		
    }
}
		catch (CodeUnitInsertionException e) {
			Msg.showError(this, null, "Length Override Error", e.getMessage());
		}
	}

	/* @Override */
	public bool isEnabledForContext(ListingActionContext context) {
		Address address = context.getAddress();
		if (address == null) {
			return false;
		}
		Program program = context.getProgram();
		Instruction instr = program.getListing().getInstructionAt(address);
		if (instr == null) {
			return false;
		}
		int alignment = program.getLanguage().getInstructionAlignment();
		return instr.getParsedLength() > alignment;
	}

	private int getDefaultOffcutLength(Program program, Instruction instr) {
		if (instr.isLengthOverridden()) {
			return instr.getLength();
		}
		AddressSet instrBody = new AddressSet(instr.getMinAddress().next(),
			instr.getMinAddress().add(instr.getParsedLength() - 1));
		Address addr =
			program.getReferenceManager().getReferenceDestinationIterator(instrBody, true).next();
		if (addr != null) {
			int offset = (int) addr.subtract(instr.getMinAddress());
			if (offset % program.getLanguage().getInstructionAlignment() == 0) {
				return offset;
			}
		}
		return 0;
	}

	private bool isOffcutFlowReference(Program program, Address address) {
		foreach (Reference reference in program.getReferenceManager().getReferencesTo(address)) {
			if (reference.getReferenceType().isFlow()) {
				return true;
			}
		}
		return false;
	}

	private void removeErrorBookmark(Program program, Address at) {
		BookmarkManager bookmarkManager = program.getBookmarkManager();
		Bookmark bookmark = bookmarkManager.getBookmark(at, BookmarkType.ERROR,
			Disassembler.ERROR_BOOKMARK_CATEGORY);
		if (bookmark != null) {
			bookmarkManager.removeBookmark(bookmark);
		}
	}

}
